    // reftype Llist of lib_ams.FShm.zd_outmsg prohibits copy
    // reftype Ptrary of lib_ams.FShm.c_chunk prohibits copy
    // reftype Llist of lib_ams.FShm.zd_chunk_free prohibits copy
    // reftype Ptrary of lib_ams.FShm.c_lane prohibits copy
    // reftype Llist of lib_ams.FShm.zd_channel prohibits copy
    // func:lib_ams.FShm..CopyCtor
    FShm(const lib_ams::FShm &rhs) = delete;
private:
